package com.clavis.reader;
import android.app.*;
import android.os.*;
import android.content.*;
import android.widget.*;
import android.view.*;
import java.util.*;
public final class DownloadsActivity extends MainActivity {
 @Override public void onCreate(Bundle state){super.onCreate(state);show(this);bar.getChildAt(0).setOnClickListener(v->finish());receive(getIntent());if(getIntent().getBooleanExtra("paste",false))paste();}
 static void show(MainActivity a){
  a.screen="Downloads";a.shell("Downloads");a.bar.getChildAt(2).setOnClickListener(v->paste(a));a.bar.addView(UiStyle.icon(a,R.drawable.ic_toolbar_more,"Download settings",()->DownloadSettings.show(a),34));
  LinearLayout actions=a.row();actions.addView(a.button("Add magnet",()->paste(a)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(a.button("Browse books",()->a.navigateBottom("Browser")),new LinearLayout.LayoutParams(0,-2,1));a.body.addView(actions);a.space(a.body,12);
  a.body.addView(a.text("Completed audio books and covers are added to your library. Change the download folder in Download settings.",12,MainActivity.MUTED,false));a.space(a.body,14);LinearLayout list=a.column();a.body.addView(list);
  a.tick=new Runnable(){public void run(){refresh(a,list);a.handler.postDelayed(this,1500);}};a.handler.post(a.tick);
  if(TorrentService.live==null&&TorrentService.current(a).stream().anyMatch(job->!job.done&&!job.paused))TorrentService.command(a,"restore","");
 }
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);receive(intent);}
 private void receive(Intent intent){String link=intent.getDataString();if(link==null&&Intent.ACTION_SEND.equals(intent.getAction()))link=intent.getStringExtra(Intent.EXTRA_TEXT);if(link!=null)offer(this,link);}
 void paste(){paste(this);}
 static void paste(MainActivity a){EditText input=new EditText(a);input.setHint("magnet:?xt=urn:btih:...");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setMaxLines(5);input.setTextColor(MainActivity.INK);new AppDialog.Builder(a).setTitle("Add magnet link").setView(input).setPositiveButton("Continue",(d,n)->offer(a,input.getText().toString())).setNegativeButton("Cancel",null).show();}
 static void offer(MainActivity a,String value){try{MagnetLink link=MagnetLink.parse(value);if(SharedDownloads.folder(a)==null){new AppDialog.Builder(a).setTitle("Choose download folder").setMessage("Choose Clavis once, then tap the magnet link again.").setPositiveButton("Choose folder",(dialog,which)->SharedDownloads.choose(a)).setNegativeButton("Cancel",null).show();return;}new AppDialog.Builder(a).setTitle("Download audiobook").setMessage(link.name+"\n\nDownload into Clavis and add supported audio files to the library when complete. Torrent transfers use your network connection, including mobile data.").setPositiveButton("Download",(d,n)->{TorrentService.command(a,"add",link.uri);if(!(a instanceof DownloadsActivity))a.navigateBottom("Downloads");}).setNegativeButton("Cancel",null).show();}catch(Exception e){new AppDialog.Builder(a).setTitle("Magnet link").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}}
 static void refresh(MainActivity a,LinearLayout list){if(!a.screen.equals("Downloads"))return;list.removeAllViews();int ebookCount=EbookDownloads.render(a,list)+CatalogDownloads.render(a,list);List<TorrentJob> jobs=TorrentService.current(a);if(jobs.isEmpty()){if(ebookCount>0)return;list.addView(a.text("No downloads yet. Browse the Gutenberg and LibriVox catalogs or add your own authorized download.",16,MainActivity.MUTED,true));return;}for(TorrentJob job:jobs){LinearLayout card=a.column();card.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));card.setBackground(a.bg(AppTheme.surface,16));TextView title=a.text(job.name,16,MainActivity.INK,true);title.setMaxLines(2);card.addView(title);a.space(card,8);String detail=job.done?job.imported?"Completed - added to library":"Completed":job.paused?"Paused":job.state;card.addView(a.text(detail,12,MainActivity.MUTED,false));ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);AppTheme.tintProgress(progress);progress.setMax(1000);progress.setProgress(Math.round(job.progress*1000));progress.setIndeterminate(job.total==0&&!job.paused&&!job.done);card.addView(progress,new LinearLayout.LayoutParams(-1,a.dp(24)));card.addView(a.text(android.text.format.Formatter.formatShortFileSize(a,job.bytes)+" / "+(job.total>0?android.text.format.Formatter.formatShortFileSize(a,job.total):"metadata pending")+"  |  "+android.text.format.Formatter.formatShortFileSize(a,job.rate)+"/s  |  "+job.peers+" peers, "+job.seeds+" seeds",11,MainActivity.MUTED,false));if(!job.done)card.addView(a.text(job.paused?"Paused":job.queued?"Waiting for a download slot":job.rate==0?"Waiting for data - ETA unavailable":DownloadEstimate.label(job.etaSeconds),12,MainActivity.MUTED,false));if(!job.error.isEmpty())card.addView(a.text(job.error,12,AppTheme.accent,false));if(!job.done)card.addView(a.text("LibreTorrent-derived engine | DHT nodes: "+job.dhtNodes+" | Reported seeds: "+job.knownSeeds,10,MainActivity.MUTED,false));LinearLayout controls=a.row();if(job.done&&!job.imported)card.addView(a.button("Save to Clavis",()->{if(SharedDownloads.folder(a)==null)SharedDownloads.choose(a);else TorrentService.command(a,"publish",job.id);}));if(!job.done)title.setOnClickListener(v->new AppDialog.Builder(a).setTitle("Transfer details").setMessage(job.state+"\nConnected peers: "+job.peers+"\nConnected seeds: "+job.seeds+"\nReported seeds: "+job.knownSeeds+"\nDHT nodes: "+job.dhtNodes).setPositiveButton("Find peers",(d,n)->TorrentService.command(a,"reannounce",job.id)).setNegativeButton("Close",null).show());if(job.done)controls.addView(a.button("Open folder",()->SharedDownloads.openDownload(a,job)),new LinearLayout.LayoutParams(0,-2,1));else controls.addView(a.button(job.paused||TorrentService.live==null?"Resume":"Pause",()->TorrentService.command(a,job.paused||TorrentService.live==null?"resume":"pause",job.id)),new LinearLayout.LayoutParams(0,-2,1));controls.addView(a.button("Remove",()->new AppDialog.Builder(a).setTitle("Remove download?").setMessage("Remove this transfer from the list. Downloaded files and library books will be kept.").setPositiveButton("Remove",(d,n)->TorrentService.command(a,"remove",job.id)).setNegativeButton("Cancel",null).show()),new LinearLayout.LayoutParams(0,-2,1));card.addView(controls);list.addView(card);a.space(list,12);}}
 @Override public void onBackPressed(){finish();}
}
